    serve({
      getContents: () =>
        new ReadableStream<Uint8Array>({
          pull(controller) {
            pulls++;
            if (offset >= bytes.length) {
              controller.close();
              return;
            }
            controller.enqueue(bytes.slice(offset, offset + 7));
            offset += 7;
          },
          cancel,
        }),
    });
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe(body.slice(0, 10));
    expect(cancel).toHaveBeenCalled();
    expect(pulls).toBeLessThan(bytes.length / 7);
  });

  it("responds 200 with the full body for unsupported body types", async () => {
    serve({ getContents: () => new URLSearchParams("a=1") });
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-1" } });
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("a=1");
  });

  it("ignores Range when size is missing or zero", async () => {
    serve({ getMeta: () => ({ type: "text/plain", etag: '"abc"' }) });
    const missing = await t.fetch("/file.txt", { headers: { range: "bytes=0-9" } });
    expect(missing.status).toBe(200);
    expect(missing.headers.get("content-range")).toBeNull();
    expect(await missing.text()).toBe(body);

    t.app = new H3();
    serve({ getMeta: () => ({ ...meta, size: 0 }) });
    const zero = await t.fetch("/file.txt", { headers: { range: "bytes=0-9" } });
    expect(zero.status).toBe(200);
    expect(zero.headers.get("content-range")).toBeNull();
    expect(await zero.text()).toBe(body);
  });

  it("overrides a user content-length header on 206", async () => {
    serve({ headers: { "content-length": "999" } });
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe(body.slice(0, 10));
  });

  it("serves the precompressed variant with its own size", async () => {
    const gz = "g".repeat(500);
    serve({
      encodings: { gzip: ".gz" },
      getMeta: (id) => (id.endsWith(".gz") ? { ...meta, size: 500, encoding: "gzip" } : meta),
      getContents: (id) => (id.endsWith(".gz") ? gz : body),
    });
    const res = await t.fetch("/file.txt", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-9" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-range")).toBe("bytes 0-9/500");
    expect(await res.text()).toBe(gz.slice(0, 10));
  });
});

